static void testAutomationTrim(const File& root,Assets& assets){
    auto p=emptyProject();p.bpm=120;p.songMode=true;p.loop=false;p.delayReturn=0;p.tracks[7].instrument=Instrument::analog;p.patterns[0].lanes[7]={{0,4,48,.8f}};
    Clip source;source.track=7;source.length=2;auto base=parameterCurve(0,7,.15f,.75f);base.points[0].curve=AutomationCurve::smooth;base.points[0].tension=.6f;
    auto offset=parameterCurve(0,7,.6f,.6f);offset.automationTrim=true;offset.beat=.25;offset.length=1.5;offset.points={{0,.6f,true},{1.5,.6f,true}};p.clips={source,base,offset};
    for(int n=0;n<=200;++n){double beat=n*.01;float original=beat<2?automationValue(base.points.data(),2,beat):trackAutomationNormal(p.tracks[7],0);float wanted=beat>=.25&&beat<1.75?jlimit(0.f,1.f,original+.2f):original;expect(std::abs(projectAutomationAt(p,0,7,beat)-wanted)<1e-6,"Trim offsets the original nonlinear curve, retaining exact untouched boundaries");}
    auto baseline=p;baseline.clips.pop_back();auto dry=render(baseline,assets,root,48000,127);auto wet=render(p,assets,root,48000,256);double difference=0;for(int c=0;c<2;++c)for(int n=0;n<48000;++n)difference+=std::abs(dry.getSample(c,n)-wet.getSample(c,n));expect(difference>.01,"nonzero Trim changes actual rendered audio");
    auto other=render(p,assets,root,48000,31);double error=0;for(int c=0;c<2;++c)for(int n=0;n<48000;++n)error=jmax(error,(double)std::abs(wet.getSample(c,n)-other.getSample(c,n)));expect(error<1e-6,"Trim playback is independent of callback size");
    p.clips.back().points={{0,.5f,true},{1.5,.5f,true}};auto neutral=render(p,assets,root,48000,127);bool exact=true;for(int c=0;c<2;++c)for(int n=0;n<48000;++n)exact&=dry.getSample(c,n)==neutral.getSample(c,n);expect(exact,"neutral Trim is byte-exact transparent over a shaped curve");
    p.clips={source,offset};p.clips.back().points={{0,.5f,true},{1.5,.5f,true}};auto staticOnly=p;staticOnly.clips.pop_back();auto a=render(p,assets,root,48000,127),b=render(staticOnly,assets,root,48000,127);exact=true;for(int c=0;c<2;++c)for(int n=0;n<48000;++n)exact&=a.getSample(c,n)==b.getSample(c,n);expect(exact,"neutral Trim preserves exact static controls without a normal-to-actual roundtrip");
    p.clips={source,base,offset};p.clips.back().points={{0,1,true},{1.5,1,true}};expect(projectAutomationAt(p,0,7,1)==1,"positive full-range Trim clamps to the maximum");p.clips.back().points={{0,0,true},{1.5,0,true}};expect(projectAutomationAt(p,0,7,1)==0,"negative full-range Trim clamps to the minimum");
    p.clips.back().points={{0,.6f,true},{1.5,.6f,true}};auto second=offset;second.points={{0,.45f,true},{1.5,.45f,true}};p.clips.push_back(second);expect(std::abs(projectAutomationAt(p,0,7,1)-(automationValue(base.points.data(),2,1)+.1f))<1e-6,"later Trim layers accumulate over the current underlying result");auto absolute=base;absolute.points={{0,.33f,true},{2,.33f,true}};p.clips.push_back(absolute);expect(std::abs(projectAutomationAt(p,0,7,1)-.33f)<1e-6,"later absolute automation overrides earlier Trim layers");
    auto path=root.getChildFile("trim.pulse");Project reopened;expect(saveProject(p,path).wasOk()&&loadProject(path,reopened).wasOk()&&reopened.clips[2].automationTrim&&reopened.clips[2].points==p.clips[2].points&&!reopened.clips.back().automationTrim,"schema 32 saves Trim identity and exact original/offset curves");
    auto json=projectToJson(p);auto retained=JSON::toString(projectToJson(reopened));json.getDynamicObject()->setProperty("schema",31);expect(projectFromJson(json,reopened).failed()&&JSON::toString(projectToJson(reopened))==retained,"Trim mislabeled as schema 31 rejects without replacing the current project");
    json=projectToJson(baseline);json.getDynamicObject()->setProperty("schema",31);for(auto& clip:*json["clips"].getArray())clip.getDynamicObject()->removeProperty("automationTrim");expect(projectFromJson(json,reopened).wasOk()&&!reopened.clips.back().automationTrim,"real schema-31 clips migrate to absolute automation");
    for(var bad:{var(1),var("true"),var()}){json=projectToJson(p);json["clips"][2].getDynamicObject()->setProperty("automationTrim",bad);expect(projectFromJson(json,reopened).failed(),"Trim flags require real booleans");}
    json=projectToJson(p);json["clips"][2].getDynamicObject()->removeProperty("automationTrim");expect(projectFromJson(json,reopened).failed(),"schema-32 clips require explicit mode metadata");
    json=projectToJson(p);json["clips"][0].getDynamicObject()->setProperty("automationTrim",true);expect(projectFromJson(json,reopened).failed(),"pattern clips cannot masquerade as Trim");
    for(int target:{6,55,101,114,116,120,121}){auto invalid=offset;invalid.automationTarget=target;invalid.automationTrack=target==120?-1:7;auto song=baseline;song.clips.push_back(invalid);Project result;expect(projectFromJson(projectToJson(song),result).failed(),"Trim rejects switches, counts, integer tunings and selectors");AutomationWrite writer;expect(!writer.begin({target,invalid.automationTrack,0,2,0,AutomationWrite::Mode::trim,.5f}),"native Trim cannot arm discrete targets");}
    Project edited;auto ops=JSON::parse(R"([{"op":"add_automation","track":7,"target":"volume","targetTrack":7,"beat":0,"length":2,"trim":true,"points":[{"beat":0,"value":0.6,"hold":true},{"beat":2,"value":0.6}]}])");
    ops[0].getDynamicObject()->setProperty("target",0);expect(applyControlEdits(baseline,ops,edited).wasOk()&&edited.clips.back().automationTrim,"MCP creates a persistent Trim overlay with existing automation operations");auto before=JSON::toString(projectToJson(edited));ops[0].getDynamicObject()->setProperty("trim",1);expect(applyControlEdits(baseline,ops,edited).failed()&&JSON::toString(projectToJson(edited))==before,"invalid MCP Trim flags reject without partial edits");
    // Actual callback-consumed relative takes must replay their original curve,
    // including nested Trim, clamps, release, Master and logarithmic targets.
    for(auto [target,destination]:std::array<std::pair<int,int>,6>{{{0,7},{1,7},{59,7},{10,7},{118,-1},{0,9}}}){
        auto song=baseline;song.tracks.resize(10);song.patterns[0].lanes.resize(10);song.tracks[9].isBus=true;song.tracks[7].mixer.output=9;song.delayReturn=.5f;song.tracks[7].send=.4f;song.tracks[7].mixer.distortion.enabled=true;
        song.clips[1]=parameterCurve(target,destination,.2f,.8f);song.clips[1].points[0].curve=AutomationCurve::easeIn;song.clips[1].points[0].tension=-.35f;
        auto under=parameterCurve(target,destination,.53f,.56f);under.automationTrim=true;song.clips.push_back(under);
        auto engine=makeEngine(song,assets,root);expect(engine->automationWrite.begin({target,destination,0,2,0,AutomationWrite::Mode::trim,.5f}),"continuous source/bus/Master/synth/effect Trim arms");AudioBuffer<float> live(2,48000);
        for(int frame=0;frame<48000;frame+=256){if(frame==4096)engine->automationWrite.control(.65f,true);if(frame==8192)engine->automationWrite.control(.4f,true);if(frame==16384)engine->automationWrite.control(.4f,false);engine->render(live.getWritePointer(0,frame),live.getWritePointer(1,frame),jmin(256,48000-frame));}
        const auto* take=engine->automationWrite.result();expect(take&&take->end==AutomationWrite::End::complete&&take->segmentCount==1,"relative capture returns to underlying curves after release");
        if(take){const auto& seg=take->segments[0];Clip clip;clip.track=7;clip.automationTarget=target;clip.automationTrack=destination;clip.automationTrim=true;clip.beat=seg.start;clip.length=seg.end-seg.start;for(int n=0;n<seg.count;++n){const auto& point=take->points[(size_t)(seg.first+n)];clip.points.push_back({point.beat-seg.start,point.value,true});}song.clips.push_back(clip);}
        auto replay=render(song,assets,root,48000,127);error=0;for(int c=0;c<2;++c)for(int n=0;n<48000;++n)error=jmax(error,(double)std::abs(live.getSample(c,n)-replay.getSample(c,n)));expect(error<1e-6,"Trim take replay matches live nonlinear layered audition across callback sizes");
        RenderSettings settings;settings.bits=32;settings.endBeat=2;settings.tailSeconds=0;auto wav=root.getChildFile("trim-"+String(target)+"-"+String(destination)+".wav");expect(renderAudio(song,assets,root,wav,settings).wasOk(),"Trim exports through the common float renderer");String issue;auto sample=assets.load(wav,issue);error=0;if(sample&&sample->audio.getNumSamples()==48000){for(int c=0;c<2;++c)for(int n=0;n<48000;++n)error=jmax(error,(double)std::abs(live.getSample(c,n)-sample->audio.getSample(c,n)));}else error=1;expect(error<1e-6,"offline Trim export agrees with actual recorded audition");
        auto seek=makeEngine(song,assets,root);seek->seekRequested.store(.7);float scratch[128];seek->render(scratch,nullptr,128);int row=destination<0?maxTracks:destination;double at=seek->position.load()-2./48000;expect(std::abs(seek->automationReadout[(size_t)row][(size_t)target].load()-projectAutomationAt(song,target,destination,at))<1e-5,"seek restores layered Trim from current timeline without history dependence");
        if(target==0&&destination==7){
            settings.startBeat=.5;settings.endBeat=1.5;auto range=root.getChildFile("trim-range.wav");expect(renderAudio(song,assets,root,range,settings).wasOk(),"Trim supports warmed-up range export");sample=assets.load(range,issue);error=0;if(sample&&sample->audio.getNumSamples()==24000){for(int c=0;c<2;++c)for(int n=0;n<24000;++n)error=jmax(error,(double)std::abs(replay.getSample(c,n+12000)-sample->audio.getSample(c,n)));}else error=1;expect(error<1e-6,"Trim range export equals the same passage in a full render");
            song.loop=true;song.markers={{"trim-loop","Trim loop",.25,1.75,0}};song.loopSection="trim-loop";auto looping=makeEngine(song,assets,root);for(int n=0;n<800;++n)looping->render(scratch,nullptr,128);double last=looping->position.load()-2./48000;if(last<.25)last+=1.5;expect(looping->completedLoops.load()>=2&&std::abs(looping->automationReadout[7][0].load()-projectAutomationAt(song,0,7,last))<1e-5,"repeated section loops restore offsets from the timeline without cumulative drift");
            PlaylistGroupStats stats;Project copied;expect(transformPlaylistGroup(song,{2},4,0,true,true,copied,&stats).wasOk()&&copied.clips.back().automationTrim&&copied.clips.back().points==song.clips[2].points,"group copying retains relative mode and exact offset points");
        }
    }
}
